module majority (
    input a, b, c,
    output out
);
    wire nand_ab, nand_bc, nand_ac;
    wire and_ab, and_bc, and_ac;

    // NAND gates for pair combinations
    nand(nand_ab, a, b);
    nand(nand_bc, b, c);
    nand(nand_ac, a, c);

    // AND gates to invert NAND results
    and(and_ab, nand_ab, nand_ab);
    and(and_bc, nand_bc, nand_bc);
    and(and_ac, nand_ac, nand_ac);

    // OR gate to combine all AND results
    or(out, and_ab, and_bc, and_ac);
endmodule

