module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

wire [3:0] xor_bits;
wire [3:0] nand_bits;

// XOR each bit of a with the corresponding bit of b
assign xor_bits = a ^ b;

// Generate NAND bits from the XOR results
assign nand_bits = ~xor_bits;

// Combine all NAND bits with AND to produce the final output
assign equal = &nand_bits;

endmodule

