module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    wire not_in0, not_in1;

    // Generate inverted inputs using NAND gates
    nand(not_in0, in[0], in[0]);
    nand(not_in1, in[1], in[1]);

    // Generate each output using NAND-based logic
    wire w0, w1, w2, w3;

    nand(w0, not_in1, not_in0);
    nand(out[1], w0, w0);  // out[1] = ~in[1]&~in[0]

    nand(w1, not_in1, in[0]);
    nand(out[2], w1, w1);  // out[2] = ~in[1]&in[0]

    nand(w2, in[1], not_in0);
    nand(out[3], w2, w2);  // out[3] = in[1]&~in[0]

    nand(w3, in[1], in[0]);
    nand(out[0], w3, w3);  // out[0] = in[1]&in[0]

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    function [3:0] decoder;
        input [1:0] in;
        begin
            case (in)
                2'b00: decoder = 4'b0001;
                2'b01: decoder = 4'b0010;
                2'b10: decoder = 4'b0100;
                2'b11: decoder = 4'b1000;
                default: decoder = 4'b0000; // Handles undefined cases
            endcase
        end
    endfunction

    assign out = decoder(in);

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);
    wire not_in0, not_in1;

    // Invert the input bits
    not (not_in1, in[1]);
    not (not_in0, in[0]);

    // Generate each output using AND gates
    and (out[0], not_in1, not_in0);
    and (out[1], not_in1, in[0]);
    and (out[2], in[1], not_in0);
    and (out[3], in[1], in[0]);
endmodule

