module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg [1:0] current_state;
    wire [1:0] next_state;

    assign next_state = reset ? 2'h0 : (current_state == 2'h2 ? 2'h0 : current_state + 1);
    assign state = current_state;

    always @(posedge clk) begin
        current_state <= next_state;
    end
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

parameter S0 = 2'b00,
          S1 = 2'b01,
          S2 = 2'b10,
          S3 = 2'b11;

reg [1:0] current_state, next_state;

always @(posedge clk) begin
    if (reset)
        current_state <= S0;
    else
        current_state <= next_state;
end

always @(*) begin
    case (current_state)
        S0: next_state = S1;
        S1: next_state = S2;
        S2: next_state = S3;
        S3: next_state = S0;
        default: next_state = S0;
    endcase
end

assign state = current_state;

endmodule

