module traffic_light (
    input clk, reset,
    output [2:0] light
);

// Define states
localparam S0 = 2'b00,
           S1 = 2'b01,
           S2 = 2'b10;

reg [1:0] current_state, next_state;

// State register with synchronous reset
always @(posedge clk) begin
    if (reset)
        current_state <= S0;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        S0: next_state = S1;
        S1: next_state = S2;
        S2: next_state = S0;
        default: next_state = S0; // Handle undefined states
    endcase
end

// Output logic
assign light = (current_state == S0) ? 3'b100 :
               (current_state == S1) ? 3'b010 :
               (current_state == S2) ? 3'b001 :
               3'b000; // Default case

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);
    reg [1:0] state_reg;
    reg [2:0] light_reg;

    localparam GREEN = 2'b00,
               YELLOW = 2'b01,
               RED = 2'b10;

    always @(posedge clk) begin
        if (reset)
            state_reg <= GREEN;
        else begin
            case (state_reg)
                GREEN:   state_reg <= YELLOW;
                YELLOW:  state_reg <= RED;
                RED:     state_reg <= GREEN;
                default: state_reg <= GREEN;
            endcase
        end
    end

    always @(*) begin
        case (state_reg)
            GREEN:   light_reg = 3'b100;
            YELLOW:  light_reg = 3'b010;
            RED:     light_reg = 3'b001;
            default: light_reg = 3'b100;
        endcase
    end

    assign light = light_reg;
endmodule

