module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // State encoding parameters
    localparam [1:0] UP    = 2'b00,
                     DOWN  = 2'b01,
                     STOP  = 2'b10;

    reg [1:0] state_reg, next_state;

    // Sequential state register with reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= UP;
        end else begin
            state_reg <= next_state;
        end
    end

    // Combinational next state logic
    always @(*) begin
        case (state_reg)
            UP: begin
                if (up_request)
                    next_state = UP;
                else
                    next_state = DOWN;
            end
            DOWN: begin
                if (down_request)
                    next_state = DOWN;
                else
                    next_state = UP;
            end
            STOP: begin
                if (up_request)
                    next_state = UP;
                else if (down_request)
                    next_state = DOWN;
                else
                    next_state = STOP;
            end
            default: next_state = UP; // Handle undefined states
        endcase
    end

    // Output current state
    assign state = state_reg;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // State encoding parameters
    localparam [1:0] UP    = 2'b00;
    localparam [1:0] DOWN  = 2'b01;
    localparam [1:0] WAIT  = 2'b10;

    reg [1:0] current_state, next_state;

    // Sequential state update with asynchronous reset
    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= UP;
        else
            current_state <= next_state;
    end

    // Combinational next state logic
    always @(*) begin
        case (current_state)
            UP: 
                next_state = down_request ? DOWN : UP;
            DOWN: 
                next_state = up_request ? WAIT : DOWN;
            WAIT: 
                next_state = up_request ? UP : WAIT;
            default: 
                next_state = UP; // Handle undefined states
        endcase
    end

    // Output assignment
    assign state = current_state;

endmodule

