module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);

wire [7:0] P0, G0;
wire [7:0] P1, G1;
wire [7:0] P2, G2;
wire [7:0] C;

// Initial Generate (G) and Propagate (P) signals
assign G0 = a & b;
assign P0 = a ^ b;

// Stage 1: Combining with distance 1
assign G1[0] = G0[0];
assign P1[0] = P0[0];
genvar i;
generate
    for (i = 1; i < 8; i = i + 1) begin : stage1
        assign G1[i] = G0[i] | (P0[i] & G0[i-1]);
        assign P1[i] = P0[i] & P0[i-1];
    end
endgenerate

// Stage 2: Combining with distance 2
assign G2[0] = G1[0];
assign P2[0] = P1[0];
assign G2[1] = G1[1];
assign P2[1] = P1[1];
generate
    for (i = 2; i < 8; i = i + 1) begin : stage2
        assign G2[i] = G1[i] | (P1[i] & G1[i-2]);
        assign P2[i] = P1[i] & P1[i-2];
    end
endgenerate

// Stage 3: Combining with distance 4 and generate final carry
assign C[0] = G0[0];
assign C[1] = G1[1];
assign C[2] = G2[2];
assign C[3] = G2[3];
generate
    for (i = 4; i < 8; i = i + 1) begin : stage3
        assign C[i] = G2[i] | (P2[i] & G2[i-4]);
    end
endgenerate

// Compute sum bits and final output
wire [7:0] sum;
assign sum[0] = P0[0];          // sum[0] = a[0]^b[0]
assign sum[7:1] = P0[7:1] ^ C[6:0];
assign out = {C[7], sum};

endmodule

