module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

    // Equality logic using XNOR for each bit and combine with AND
    wire [3:0] eq_bit;
    xnor(eq_bit[0], a[0], b[0]);
    xnor(eq_bit[1], a[1], b[1]);
    xnor(eq_bit[2], a[2], b[2]);
    xnor(eq_bit[3], a[3], b[3]);
    wire eq;
    and(eq, eq_bit[0], eq_bit[1], eq_bit[2], eq_bit[3]);

    // Greater than logic: a > b when a3 > b3 or (a3 == b3 and a2 > b2) etc.
    wire gt3, gt2, gt1, gt0;
    wire a3_gt_b3, a2_gt_b2, a1_gt_b1, a0_gt_b0;

    // Since a and b are 4-bit, we need to chain comparisons
    // Assuming a > b if any bit is greater and higher bits are equal
    // This requires inverted signals for higher bits being equal
    wire not_a3_eq_b3, not_a2_eq_b2, not_a1_eq_b1, not_a0_eq_b0;
    xnor(not_a3_eq_b3, a[3], b[3]); // Invert XNOR to get a3 > b3
    and(gtz, not_a3_eq_b3, a[3], b[3]); // Actually, simpler: use direct comparison

    // Correct approach for gt: 
    wire term3, term2, term1, term0;
    and(term3, a[3], ~b[3]); // a3 > b3
    and(term2, eq_bit[3], a[2], ~b[2]); // a2 > b2 when a3 == b3
    and(term1, eq_bit[3], eq_bit[2], a[1], ~b[1]); // a1 > b1 when a3==b3 and a2==b2
    and(term0, eq_bit[3], eq_bit[2], eq_bit[1], a[0], ~b[0]); // a0 > b0 when others equal
    or(gT, term3, term2, term1, term0);

    // Less than logic is the inverse of gt when a != b
    wire lt;
    not(lt, gT) & ~eq; // lt is true when a < b (not equal and gt is false)

    // Handle equal case
    assign eq = eq; // Already computed

    // Output assignments
    assign gt = gT;
    assign lt = lt;
    assign eq = eq;

endmodule

