    input rst,
    output [7:0] count
);

    reg [7:0] Q;
    wire [7:0] Q_next;

    // Next state logic
    assign Q_next[0] = Q[7];
    assign Q_next[1] = Q[6] ^ Q[7];
    assign Q_next[2] = Q[5] ^ Q[6];
    assign Q_next[3] = Q[4] ^ Q[5];
    assign Q_next[4] = Q[3] ^ Q[4];
    assign Q_next[5] = Q[2] ^ Q[3];
    assign Q_next[6] = Q[1] ^ Q[2];
    assign Q_next[7] = Q[0] ^ Q[1];

    // State update with synchronous reset
    always @(posedge clk) begin
        if (rst)
            Q <= 8'b0;
        else
            Q <= Q_next;
    end

    // Output assignment
    assign count = Q;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  parameter [1:0] c0 = 2'b00,
                  c1 = 2'b01,
                  c2 = 2'b10,
                  c3 = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge clk) begin
    if (!resetn)
      current_state <= c0;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      c0: begin
        if (r[0])
          next_state = c0;
        else if (r[1])
          next_state = c1;
        else if (r[2])
          next_state = c2;
        else
          next_state = c3;
      end
      c1: begin
        if (r[0])
          next_state = c0;
        else if (r[1])
          next_state = c1;
        else if (r[2])
          next_state = c2;
        else
          next_state = c3;
      end
      c2: begin
        if (r[0])
          next_state = c0;
        else if (r[1])
          next_state = c1;
        else if (r[2])
          next_state = c2;
        else
          next_state = c3;
      end
      c3: begin
        if (r[0])
          next_state = c0;
        else if (r[1])
          next_state = c1;
        else if (r[2])
          next_state = c2;
        else
          next_state = c3;
      end
      default: next_state = c0;
    endcase
  end

  assign g = (current_state == c0) ? 3'b000 :
              (current_state == c1) ? 3'b001 :
              (current_state == c2) ? 3'b010 :
              3'b011;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam GREEN  = 2'b00,
             YELLOW = 2'b01,
             RED    = 2'b10;

  reg [1:0] current_state, next_state;

  always @(posedge clk) begin
    if (!resetn)
      current_state <= GREEN;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      GREEN:  next_state = (r == 3'b010) ? YELLOW : GREEN;
      YELLOW: next_state = (r == 3'b011) ? RED   : YELLOW;
      RED:    next_state = (r == 3'b100) ? GREEN : RED;
      default:next_state = GREEN;
    endcase
  end

  assign g = (current_state == GREEN)  ? 3'b010 :
              (current_state == YELLOW) ? 3'b011 : 3'b100;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam S0 = 2'b00,
             S1 = 2'b01,
             S2 = 2'b10,
             S3 = 2'b11;

  reg [1:0] current_state, next_state;

  // State register
  always @(posedge clk) begin
    if (!resetn)
      current_state <= S0;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      S0: next_state = r[0] ? (r[1] ? S2 : S1) : S0;
      S1: next_state = r[0] ? (r[1] ? S3 : S2) : S1;
      S2: next_state = r[0] ? (r[1] ? S0 : S3) : S2;
      S3: next_state = r[0] ? (r[1] ? S1 : S0) : S3;
      default: next_state = S0;
    endcase
  end

  // Output logic
  assign g[0] = (current_state == S0);
  assign g[1] = (current_state == S1) && !r[0];
  assign g[2] = (current_state == S2) && !r[1];

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam [1:0] IDLE = 2'b00,
                   GNT1 = 2'b01,
                   GNT2 = 2'b10,
                   GNT3 = 2'b11;

  reg [1:0] state, next_state;

  always @(posedge clk) begin
    if (!resetn)
      state <= IDLE;
    else
      state <= next_state;
  end

  always @(*) begin
    case (state)
      IDLE: begin
        if (r[0])
          next_state = GNT1;
        else if (r[1])
          next_state = GNT2;
        else if (r[2])
          next_state = GNT3;
        else
          next_state = IDLE;
      end
      GNT1: next_state = r[0] ? GNT1 : IDLE;
      GNT2: next_state = r[1] ? GNT2 : IDLE;
      GNT3: next_state = r[2] ? GNT3 : IDLE;
      default: next_state = IDLE;
    endcase
  end

  assign g = (state == IDLE) ? 3'b000 :
             (state == GNT1) ? 3'b001 :
             (state == GNT2) ? 3'b010 :
             (state == GNT3) ? 3'b100 :
             3'b000;

endmodule

