module TopModule (
  input p1a,
  input p1b,
  input p1c,
  input p1d,
  input p1e,
  input p1f,
  output p1y,
  input p2a,
  input p2b,
  input p2c,
  input p2d,
  output p2y
);

  wire p1y_temp;
  wire p2y_temp;
  wire p1a_p2b;

  // Calculate p1a_p2b as (p1a & p1b) | p2a & p2b
  assign p1a_p2b = (p1a & p1b) | (p2a & p2b);

  // Calculate p1y_temp as (p1a_p2b & p1c) | (p1d & p1e & p1f)
  assign p1y_temp = (p1a_p2b & p1c) | (p1d & p1e & p1f);

  // Assign outputs
  assign p1y = p1y_temp;
  assign p2y = (p2c & p2d) | p1a_p2b;

endmodule

module TopModule (
  input p1a,
  input p1b,
  input p1c,
  input p1d,
  input p1e,
  input p1f,
  output p1y,
  input p2a,
  input p2b,
  input p2c,
  input p2d,
  output p2y
);

  wire p1y_interm, p2y_interm;
  wire p1a_p1b, p1d_p1e, p2a_p2b, p2c_p2d;

  // First layer AND operations
  assign p1a_p1b = p1a & p1b;
  assign p1d_p1e = p1d & p1e;
  assign p2a_p2b = p2a & p2b;
  assign p2c_p2d = p2c & p2d;

  // Second layer OR operations
  assign p1y_interm = p1a_p1b | p1c;
  assign p2y_interm = p1d_p1e | p2a_p2b;

  // Final output combinations
  assign p1y = p1y_interm | (p1f & p1y_interm);
  assign p2y = p2y_interm | p2c_p2d;

endmodule

