);

  // Rule 1: Shut off computer when CPU is overheated
  always @(*) begin
    shut_off_computer = cpu_overheated;
  end

  // Rule 2: Keep driving if either arrived or gas_tank_empty is high
  // Rule 3: Stop driving if both arrived and gas_tank_empty are low
  always @(*) begin
