);

  // Rule 1: CPU overheating causes shutdown
  always @(*) begin
    if (cpu_overheated)
      shut_off_computer = 1'b1;
    else
      shut_off_computer = 1'b0;
  end

  // Rule 2: Shutdown is permanent until reset (inferred via reset absence)
  // Since no reset is provided, shutdown persists for the simulation

  // Rule 3: Stop driving when arrived or low fuel, else continue
  always @(*) begin
    if (arrived || gas_tank_empty)
      keep_driving = 1'b0;
    else
      keep_driving = 1'b1;
  end

