);

  // Rule 1: Shut down computer if CPU is overheated
  always @(*) begin
    if (cpu_overheated)
      shut_off_computer = 1'b1;
    else
      shut_off_computer = 1'b0;
  end

  // Rule 2: Keep driving if either arrived or gas_tank_empty is low (interpreted as active)
  always @(*) begin
    if (arrived || !gas_tank_empty)
      keep_driving = 1'b1;
    else
