module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
);

  // Rule 1: CPU overheating resets keep_driving and triggers shut_off
  always @* begin
    if (cpu_overheated) begin
      keep_driving = 0;
      shut_off_computer = 1;
    end
    // Rule 2: Gas tank low resets keep_driving
    else if (gas_tank_empty) begin
      keep_driving = 0;
      shut_off_computer = 0;
    end
    // Rule 3: Arrival resets shut_off and restores keep_driving
    else if (arrived) begin
      shut_off_computer = 0;
      keep_driving = 1;
    end
    // Default: maintain current state
    else begin
      keep_driving = keep_driving;
      shut_off_computer = shut_off_computer;
    end
  end

endmodule

