module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  localparam STATE_IDLE = 2'b01;
  localparam STATE_GRANT = 2'b10;
  localparam STATE_WAIT = 2'b11;

  reg [1:0] state_reg;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state_reg <= STATE_IDLE;
    end else begin
      case (state_reg)
        STATE_IDLE: begin
          if (train_valid && !train_taken)
            state_reg <= STATE_GRANT;
          else
            state_reg <= STATE_IDLE;
        end
        STATE_GRANT: begin
          if (train_valid && train_taken)
            state_reg <= STATE_WAIT;
          else
            state_reg <= STATE_GRANT;
        end
        STATE_WAIT: begin
          if (train_valid && !train_taken)
            state_reg <= STATE_IDLE;
          else
            state_reg <= STATE_WAIT;
        end
        default: state_reg <= STATE_IDLE;
      endcase
    end
  end

  assign state = state_reg;

endmodule

module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  parameter INIT = 2'b00;
  parameter CLASS = 2'b01;
  parameter DECIDE = 2'b10;
  parameter RETURN = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= INIT;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      INIT: begin
        next_state = (train_valid && !train_taken) ? CLASS : INIT;
      end
      CLASS: begin
        next_state = (train_valid && !train_taken) ? DECIDE : CLASS;
      end
      DECIDE: begin
        next_state = (!train_valid) ? RETURN : DECIDE;
      end
      RETURN: begin
        next_state = RETURN;
