module TopModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);

  reg [6:0] stack;

  always @(posedge clk) begin
    if (enable) begin
      stack <= {stack[5:0], S}; // Shift left and append S to the MSB
    end
  end

  always @(*) begin
    if (enable) begin
      Z = stack[6]; // MSB of the current stack value
    end else begin
      case ({A, B, C})
        3'b000: Z = 1'b0;
        3'b001: Z = 1'b0;
        3'b010: Z = 1'b1;
        3'b011: Z = 1'b1;
        3'b100: Z = 1'b0;
        3'b101: Z = 1'b1;
        3'b110: Z = 1'b1;
        3'b111: Z = 1'b1;
      endcase
    end
  end

endmodule

