module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);

  localparam S0 = 2'b00,
             S1 = 2'b01,
             S2 = 2'b10;

  reg [1:0] current_state, next_state;

  // State transition logic
  always @(*) begin
    case (current_state)
      S0: next_state = x ? S1 : S0;
      S1: next_state = x ? S2 : S0;
      S2: next_state = x ? S2 : S0;
      default: next_state = S0;
    endcase
  end

  // State register
  always @(posedge clk or negedge aresetn) begin
    if (!aresetn) begin
      current_state <= S0;
    end else begin
      current_state <= next_state;
    end
  end

  // Output logic
  always @(*) begin
    z = (current_state == S2) && x;
  end

endmodule

