module TopModule (
  input a,
  input b,
  input cin,
  output cout,
  output sum
);

  wire a_xor_b;

  // First XOR gate with delay 3
  xor #3 xor1(a_xor_b, a, b);

  // Second XOR gate with rise delay 1, fall delay 4
  xor #(1,4) xor2(sum, a_xor_b, cin);

  // AND gates for cout calculation
  wire and1_out, and2_out;
  and #2 and1(and1_out, a, b);          // Delay 2
  and #3 and2(and2_out, cin, a_xor_b);  // Delay 3

  // OR gate for cout with delay 3
  or #3 or1(cout, and1_out, and2_out);  // Delay 3

endmodule

module TopModule (
  input a,
  input b,
  input cin,
  output cout,
  output sum
);
  wire n1, n2, n3, xor_ab;
  wire n4, n5, n6;
  wire n7, n8, n9;

  // XOR for sum (a XOR b XOR cin)
  nand(n1, a, b);
  nand(n2, a, n1);
  nand(n3, b, n1);
  nand(xor_ab, n2, n3);

  nand(n4, xor_ab, cin);
  nand(n5, xor_ab, n4);
  nand(n6, cin, n4);
  nand(sum, n5, n6);

  // Carry-out (a AND b OR a AND cin OR b AND cin)
  nand(n7, a, a);  // ~a
  nand(n8, b, b);  // ~b
  nand(n9, cin, cin);  // ~cin

  nand(n10, n7, n8);  // a AND b
  nand(n11, n7, n9);  // a AND cin
  nand(n12, n8, n9);  // b AND cin

  nand(n13, n10, n10);  // a AND b (from nand)
  nand(n14, n11, n11);  // a AND cin
  nand(n15, n12, n12);  // b AND cin

  nand(n16, n13, n14);  // (a AND b) OR (a AND cin)
  nand(n17, n16, n16);  // ~((a AND b) OR (a AND cin))
  nand(n18, n17, n15);  // final carry-out
