  assign c1 = g[0];
  assign c2 = g[1] | (p[1] & g[0]);
  assign c3 = g[2] | (p[2] & g[1]) | (p[2] & p[1] & g[0]);
  assign c4 = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]);

  assign carry[0] = 1'b0;
  assign carry[1] = c1;
  assign carry[2] = c2;
  assign carry[3] = c3;
  assign carry[4] = c4;

  // Sum calculations
  assign sum[0] = p[0];
  assign sum[1] = p[1] ^ carry[0];
  assign sum[2] = p[2] ^ carry[1];
  assign sum[3] = p[3] ^ carry[2];
  assign sum[4] = carry[3];

