  localparam [2:0] S_0 = 3'b000,
                   S_1 = 3'b001,
                   S_2 = 3'b010,
                   S_3 = 3'b011,
                   S_4 = 3'b100;

  reg [2:0] current_state, next_state;

  // State register
  always @(posedge clk) begin
    if (reset)
      current_state <= S_0;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      S_0: next_state = w ? S_1 : S_0;
      S_1: next_state = w ? S_1 : S_2;
      S_2: next_state = w ? S_3 : S_0;
      S_3: next_state = w ? S_4 : S_2;
      S_4: next_state = w ? S_1 : S_2;
      default: next_state = S_0;
    endcase
  end

  // Output logic
  assign z = (current_state == S_2 || current_state == S_4);

endmodule

