  // Compute a XOR b
  nand(temp1, a, b);
  nand(temp2, a, temp1);
  nand(temp3, b, temp1);
  nand(temp4, temp2, temp3);
  wire ab_xor = temp4;

  // Compute a AND b
  wire temp5, temp6;
  nand(temp5, a, b);
  nand(temp6, temp5, temp5);
  wire ab_and = temp6;

  // Compute (a XOR b) XOR c
