  nand(temp7, ab_xor, c);
  nand(temp8, ab_xor, temp7);
  nand(temp9, c, temp7);
  nand(temp10, temp8, temp9);
  wire sum = temp10;

  // Compute carry-out
  wire temp11, temp12;
  nand(temp11, ab_xor, ab_and);
  nand(temp12, temp11, temp11);
  wire carry = temp12;

  assign out = {sum, carry};

