module TopModule (
  input clk,
  input reset,
  input w,
  output z
);

  reg [2:0] S, N;

  // State register with synchronous reset
  always @(posedge clk) begin
    if (reset)
      S <= 3'b000;
    else
      S <= N;
  end

  // Next state logic based on current state and input
  always @(*) begin
    case (S)
      3'b000: N = w ? 3'b001 : 3'b000;
      3'b001: N = w ? 3'b010 : 3'b000;
      3'b010: N = w ? 3'b010 : 3'b011;
      3'b011: N = w ? 3'b100 : 3'b000;
      3'b100: N = w ? 3'b101 : 3'b011;
      3'b101: N = w ? 3'b001 : 3'b011;
      default: N = 3'b000; // Handle unexpected states
    endcase
  end

