  not #5 (not_a, a);
  not #5 (not_b, b);
  not #5 (not_c, c);
  not #5 (not_d, d);

  // Intermediate terms (AND/NOT combinations)
  and #5 (t1, not_a, not_b, not_c);
  and #5 (t2, not_a, not_b, d);
  and #5 (t3, a, not_c, not_d);
  and #5 (t4, a, c, not_d);

  // Combine terms with OR gates
  or #5 (s1, t1, t2);
  or #5 (s2, t3, t4);

