module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);

  localparam WALK_RIGHT = 1'b0;
  localparam WALK_LEFT = 1'b1;

  reg state;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= WALK_RIGHT;
    end else begin
      case (state)
        WALK_RIGHT: state <= bump_left ? WALK_LEFT : WALK_RIGHT;
        WALK_LEFT:  state <= bump_right ? WALK_RIGHT : WALK_LEFT;
        default:     state <= WALK_RIGHT;
      endcase
    end
  end

  assign walk_right = (state == WALK_RIGHT);
  assign walk_left  = (state == WALK_LEFT);

endmodule

module TopModule (
