      current_state <= STATE_RIGHT;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      STATE_RIGHT: next_state = bump_left ? STATE_LEFT : STATE_RIGHT;
      STATE_LEFT:  next_state = bump_right ? STATE_RIGHT : STATE_LEFT;
      default:     next_state = STATE_RIGHT;
    endcase
  end

  assign walk_right = (current_state == STATE_RIGHT);
  assign walk_left  = ~walk_right;

endmodule

module TopModule (
