      state <= WALK_LEFT;
    else
      state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state)
      WALK_LEFT: 
        next_state = bump_right ? WALK_RIGHT : WALK_LEFT;
      WALK_RIGHT: 
        next_state = bump_left ? WALK_LEFT : WALK_RIGHT;
      default: 
