endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);

  localparam LEFT = 1'b0;
  localparam RIGHT = 1'b1;

  reg current_state;
  reg next_state;

  // Combinational next state logic
  always @(*) begin
    case (current_state)
      LEFT: next_state = bump_right ? RIGHT : LEFT;
      RIGHT: next_state = bump_left ? LEFT : RIGHT;
      default: next_state = LEFT;
    endcase
  end

  // Sequential state update
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= LEFT;
    end else begin
      current_state <= next_state;
    end
  end

  // Output logic
  assign walk_left = (current_state == LEFT);
  assign walk_right = (current_state == RIGHT);

endmodule

module TopModule (
