);

  localparam RIGHT = 1'b0;
  localparam LEFT = 1'b1;

  reg state;

  assign walk_right = state;
  assign walk_left = ~state;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= RIGHT;
    end else begin
      case (state)
        RIGHT: state <= bump_left ? LEFT : RIGHT;
        LEFT:  state <= bump_right ? RIGHT : LEFT;
        default: state <= RIGHT;
      endcase
    end
  end

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  reg [1:0] state_reg, state_next;
  localparam Halted = 2'b00,
             RightWalking = 2'b01,
             LeftWalking = 2'b10,
             Spin = 2'b11;

  always @(posedge clk or posedge areset) begin
    if (areset)
      state_reg <= Halted;
    else
      state_reg <= state_next;
  end

  always @* begin
    state_next = state_reg;
    case (state_reg)
      Halted: begin
        if (bump_right && ground)
          state_next = RightWalking;
        else if (bump_left && ground)
          state_next = LeftWalking;
        else if (bump_right && bump_left)
          state_next = Spin;
        else
          state_next = Halted;
      end
      RightWalking: begin
        if (!ground)
          state_next = Halted;
        else
          state_next = RightWalking;
      end
      LeftWalking: begin
        if (!ground)
          state_next = Halted;
        else
          state_next = LeftWalking;
      end
      Spin: begin
        if (ground)
          state_next = Halted;
        else
          state_next = Spin;
      end
      default: state_next = Halted;
    endcase
  end

  assign walk_left = (state_reg == LeftWalking);
  assign walk_right = (state_reg == RightWalking);
  assign aaah = !((state_reg == RightWalking) || (state_reg == LeftWalking));

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  reg [1:0] state_reg, state_next;
  localparam IDLE = 2'b00,
             LEFT = 2'b01,
             RIGHT = 2'b10,
             RIGHT_LEFT = 2'b11;

  always @(posedge clk or posedge areset) begin
    if (areset)
      state_reg <= IDLE;
    else
      state_reg <= state_next;
  end

  always @* begin
    case (state_reg)
      IDLE: begin
        if (ground)
          state_next = RIGHT;
        else if (bump_left)
          state_next = LEFT;
        else
          state_next = IDLE;
      end
      LEFT: begin
        if (ground)
          state_next = RIGHT;
        else if (bump_left)
          state_next = LEFT;
        else if (bump_right)
          state_next = RIGHT_LEFT;
        else
          state_next = LEFT;
      end
      RIGHT: begin
        if (ground)
          state_next = RIGHT;
        else if (bump_right)
          state_next = RIGHT;
        else if (bump_left)
          state_next = LEFT;
        else
          state_next = RIGHT;
      end
      RIGHT_LEFT: begin
        if (ground)
          state_next = RIGHT;
        else if (bump_left)
          state_next = LEFT;
        else if (bump_right)
          state_next = RIGHT;
        else
          state_next = RIGHT_LEFT;
      end
      default: state_next = IDLE;
    endcase
  end

  assign walk_left = (state_reg == LEFT);
  assign walk_right = (state_reg == RIGHT);
  assign aaah = (state_reg == LEFT) || (state_reg == RIGHT);

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  // State encoding
  localparam [1:0] AA = 2'b00,
                   WB = 2'b01,
                   CW = 2'b10,
                   XX = 2'b11;

  reg [1:0] current_state, next_state;

  // State register with asynchronous reset
  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= AA;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      AA: begin
        if (ground)
          next_state = WB;
        else if (bump_left)
          next_state = CW;
        else
          next_state = AA;
      end
      WB: begin
        if (ground)
          next_state = WB;
        else
          next_state = AA;
      end
      CW: begin
        if (ground)
          next_state = CW;
        else if (bump_right)
          next_state = AA;
        else
          next_state = XX;
      end
      XX: begin
        next_state = AA;
      end
      default: next_state = AA;
    endcase
  end

  // Output logic
  assign walk_left = (current_state == WB);
  assign walk_right = (current_state == CW);
  assign aaah = (current_state == AA) || (current_state == CW);

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  localparam [1:0] WALK_RIGHT_A = 2'b00;
  localparam [1:0] WALK_RIGHT_B = 2'b01;
  localparam [1:0] WALK_LEFT_A  = 2'b10;
  localparam [1:0] WALK_LEFT_B  = 2'b11;

  reg [1:0] state, next_state;

  // State register
  always @(posedge clk or posedge areset) begin
    if (areset) state <= WALK_RIGHT_A;
    else state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state)
      WALK_RIGHT_A: begin
        next_state = ground ? WALK_RIGHT_A :
                    bump_right ? WALK_RIGHT_B : WALK_LEFT_A;
      end
      WALK_RIGHT_B: begin
        next_state = ground ? WALK_RIGHT_A :
                    bump_right ? WALK_LEFT_A : WALK_RIGHT_B;
      end
      WALK_LEFT_A: begin
        next_state = ground ? WALK_LEFT_A :
                    bump_left ? WALK_LEFT_B : WALK_RIGHT_B;
      end
      WALK_LEFT_B: begin
        next_state = ground ? WALK_LEFT_B :
                    bump_left ? WALK_RIGHT_B : WALK_LEFT_B;
      end
      default: next_state = WALK_RIGHT_A;
    endcase
  end

  // Output logic
  assign walk_right = (state == WALK_RIGHT_A || state == WALK_RIGHT_B);
  assign walk_left = (state == WALK_LEFT_A || state == WALK_LEFT_B);
  assign aaah = (state == WALK_RIGHT_A || state == WALK_LEFT_A);

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  reg [1:0] current_state, next_state;
  localparam [1:0] GROUND = 2'b00,
                   WALK_LEFT = 2'b01,
                   WALK_RIGHT = 2'b10,
                   STOP = 2'b11;

  // State register with asynchronous reset
  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= GROUND;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      GROUND: begin
        if (bump_left)
          next_state = WALK_LEFT;
        else if (bump_right)
          next_state = WALK_RIGHT;
        else
          next_state = GROUND;
      end
      WALK_LEFT: begin
        if (ground)
          next_state = GROUND;
        else
          next_state = WALK_LEFT;
      end
      WALK_RIGHT: begin
        if (ground)
          next_state = GROUND;
        else
          next_state = WALK_RIGHT;
      end
      STOP: next_state = STOP; // Unreachable per problem spec
      default: next_state = GROUND;
    endcase
  end

  // Output logic
  assign walk_left = (current_state == WALK_LEFT);
  assign walk_right = (current_state == WALK_RIGHT);
  assign aaah = !(current_state == WALK_LEFT || current_state == WALK_RIGHT);

endmodule

