  assign q1_next = (x & Q0) | (~x & ~Q0);  // XOR gate formed by AND and NOT
  assign q2_next = Q1 & ~Q0;  // Q2 next state is Q1 AND NOT Q0

  // State updates on clock edge
  always @(posedge clk) begin
    Q0 <= q0_next;
    Q1 <= q1_next;
    Q2 <= q2_next;
  end

