module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // State decoding (one-hot encoding)
  wire current_state_is_B3 = state[9];
  wire current_state_is_S1 = state[8];
  wire current_state_is_S2 = state[7];
  wire current_state_is_S3 = state[6];
  wire current_state_is_S4 = state[5];
  wire current_state_is_S5 = state[4];
  wire current_state_is_S6 = state[3];
  wire current_state_is_S7 = state[2];
  wire current_state_is_S8 = state[1];
  wire current_state_is_S9 = state[0];

  // Next state logic
  assign B3_next = current_state_is_S1 & d;
  assign S_next = (current_state_is_S1 & ~d) | (current_state_is_S7 & ack);
  assign S1_next = current_state_is_S6 & d;

  // Counter control logic
  assign Count_next = (current_state_is_S2) | (current_state_is_S4 & done_counting);
  assign Wait_next = (current_state_is_S3) | (current_state_is_S5 & done_counting);

  // Done signal logic
  assign done = current_state_is_S9;
  assign counting = current_state_is_S4;

  // Shift enable logic (assumes active-high in S4)
  assign shift_ena = (current_state_is_S1) | (current_state_is_S7);

endmodule

