module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     wire [15:1] P = A[15:1];
     wire [15:1] G = A[31:16];
     wire [15:1] M = B[15:1];
     wire [15:1] X = B[31:16];

     // Compute M' and X' by reversing bits of M and X respectively
     wire [15:1] M_prime;
     wire [15:1] X_prime;
     genvar i;
     generate
         for (i = 1; i <= 15; i = i + 1) begin : reverse_bits
             assign M_prime[i] = M[16 - i];
             assign X_prime[i] = X[16 - i];
         end
     endgenerate

     // First stage carry look-ahead
     wire [15:1] C1;
     wire [15:1] S1;
     generate
         for (i = 1; i <= 15; i = i + 1) begin : stage1
             assign C1[i] = (P[i-1] & G[i]) | (P[i-1] & M'[i-1]) | (G[i] & M'[i-1]);
             assign S1[i] = P[i] ^ (P[i] & G[i]) ^ (P[i] & M'[i-1]);
         end
     endgenerate

     // Second stage carry look-ahead
     wire [15:1] C2;
     wire [15:1] S2;
     generate
         for (i = 1; i <= 15; i = i + 1) begin : stage2
             assign C2[i] = (S1[i-1] & G[i]) | (S1[i-1] & M'[i-1]) | (G[i] & M'[i-1]);
             assign S2[i] = S1[i] ^ (S1[i] & G[i]) ^ (S1[i] & M'[i-1]);
         end
     endgenerate

     // Third stage with Cin
     wire [15:1] C3;
     wire [15:1] S3;
     generate
         for (i = 1; i <= 15; i = i + 1) begin : stage3
             assign C3[i] = (S2[i-1] & G[i]) | (S2[i-1] & M'[i-1]) | (G[i] & M'[i-1]);
             assign S3[i] = S2[i] ^ (S2[i] & G[i]) ^ (S2[i] & M'[i-1]);
         end
     endgenerate

     // Compute final sum and carry-out
     wire carry_out;
     assign carry_out = (S3[15] & G[15]) | (S3[15] & M'[15]) | (G[15] & M'[15]);
     assign C32 = carry_out;
     assign S = {S3, carry_out};

endmodule

module adder_32bit(A,B,S,C32);
     input [32:1] A;
