     wire [15:1] P = A[15:1];
     wire [15:1] G = A[31:16];
     wire [15:1] M = B[15:1];
     wire [15:1] Y = B[31:16];

     wire Cin = A[1];
     wire [15:1] Cout = Cin + P + G;
     wire [15:1] Sum = P ^ G ^ Cin;
     wire [15:1] C = Sum ^ M;
     wire Cout_final = Cin + P[1] + G[1] + M[1];

     assign S[1] = C[1];
     assign S[15:2] = C;
     assign S[31:16] = Y;
     assign C32 = Cout_final;

endmodule

