     assign sum_lower = A_upper[15:0] + B_upper[15:0] + 1'b0;
     assign cout_lower = sum_lower[16];
     assign S[15:0] = sum_lower[15:0];

     // Upper 16-bit addition with Cin=cout_lower
     assign sum_upper = A_upper[31:16] + B_upper[31:16] + cout_lower;
     assign cout_upper = sum_upper[32];
     assign S[31:16] = sum_upper[31:16];

