module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);
    wire [7:0] carry;

    assign carry[0] = cin;

    // Bit 0
    assign sum[0] = a[0] ^ b[0] ^ carry[0];
    assign carry[1] = (a[0] & b[0]) | (a[0] & carry[0]) | (b[0] & carry[0]);

    // Bit 1
    assign sum[1] = a[1] ^ b[1] ^ carry[1];
    assign carry[2] = (a[1] & b[1]) | (a[1] & carry[1]) | (b[1] & carry[1]);

    // Bit 2
    assign sum[2] = a[2] ^ b[2] ^ carry[2];
    assign carry[3] = (a[2] & b[2]) | (a[2] & carry[2]) | (b[2] & carry[2]);

    // Bit 3
    assign sum[3] = a[3] ^ b[3] ^ carry[3];
    assign carry[4] = (a[3] & b[3]) | (a[3] & carry[3]) | (b[3] & carry[3]);

    // Bit 4
    assign sum[4] = a[4] ^ b[4] ^ carry[4];
    assign carry[5] = (a[4] & b[4]) | (a[4] & carry[4]) | (b[4] & carry[4]);

    // Bit 5
    assign sum[5] = a[5] ^ b[5] ^ carry[5];
    assign carry[6] = (a[5] & b[5]) | (a[5] & carry[5]) | (b[5] & carry[5]);

    // Bit 6
    assign sum[6] = a[6] ^ b[6] ^ carry[6];
    assign carry[7] = (a[6] & b[6]) | (a[6] & carry[6]) | (b[6] & carry[6]);

    // Bit 7
    assign sum[7] = a[7] ^ b[7] ^ carry[7];
    assign carry[8] = (a[7] & b[7]) | (a[7] & carry[7]) | (b[7] & carry[7]);

    assign cout = carry[8];
endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);
    wire [7:0] carry;

    assign carry[0] = (a[0] & b[0]) | ((a[0] ^ b[0]) & cin);
    assign sum[0] = a[0] ^ b[0] ^ cin;

    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin : adder_stage
            assign carry[i] = (a[i] & b[i]) | ((a[i] ^ b[i]) & carry[i-1]);
            assign sum[i] = a[i] ^ b[i] ^ carry[i-1];
        end
    endgenerate

    assign cout = carry[7];
endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry (0 or 1)
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    // Precalculated constants for BCD adjustment
    localparam [3:0] LOW  = 4'd6;  // Add 6 when sum >=10 (after first adder)
    localparam [3:0] HIGH = 4'd3;  // Add 3 when sum >=12 (after second adder)

    // Step 1: First adder with carry
    wire [4:0] first_sum = A + B + Cin;
    wire [3:0] sum1 = first_sum[3:0];
    wire carry1 = first_sum[4];

    // Step 2: Adjust first sum if >=10
    wire [3:0] sum2 = (sum1 >= 4'd10) ? (sum1 + LOW) : sum1;

    // Step 3: Second adder with adjusted sum and carry1
    wire [4:0] second_sum = sum2 + carry1;
    assign Sum = second_sum[3:0];
    assign Cout = second_sum[4];

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    // Stage 1: Add lower 3 bits and generate initial carry
    wire [2:0] sum_lower = A[2:0] + B[2:0] + Cin;
    wire carry_lower = (sum_lower >= 5) ? 1'b1 : 1'b0;
    wire [1:0] sum_lower_adjusted = sum_lower[1:0];

    // Stage 2: Process upper 3 bits with adjusted sum and carry
    wire [2:0] sum_upper = A[3:1] + B[3:1] + carry_lower;
    wire carry_upper = (sum_upper >= 5) ? 1'b1 : 1'b0;
    wire [1:0] sum_upper_adjusted = sum_upper[1:0];

    // Stage 3: Adjust sum and carry for final output
    wire [2:0] sum_final = sum_upper_adjusted + (carry_upper ? 3'd1 : 3'd0);
    wire carry_final = (sum_final >= 5) ? 1'b1 : 1'b0;
    wire [1:0] sum_final_adjusted = sum_final[1:0];

    // Assign outputs
    assign Sum = {carry_final, sum_final_adjusted[1:0]};
    assign Cout = carry_final;

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    wire [4:0] temp_sum = A + B + Cin; // Compute sum as 5-bit value
    wire need_adj = (temp_sum >= 5'd10); // Check if adjustment needed

    assign Cout = need_adj; // Carry-out is 1 when adjustment needed

    // Apply adjustment: add 6 (0110) if sum >=10, else use original lower 4 bits
    assign Sum = need_adj ? (temp_sum[3:0] + 4'd6) : temp_sum[3:0];

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);
    wire [4:0] temp_sum;
    assign temp_sum = A + B + Cin;

    // If sum >=10, adjust by subtracting 6 (0x06)
    assign Sum = (temp_sum >= 5'd10) ? (temp_sum - 5'd6) : temp_sum[3:0];
    assign Cout = (temp_sum >= 5'd10) ? 1'b1 : 1'b0;
endmodule

