module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    wire [3:0] eq_high; // Indicates if higher bits (i+1 to 3) are equal
    wire [3:0] gt;      // Indicates if A[i] > B[i] with higher bits equal

    // Compute higher bits being equal (eq_high[0] = 1, eq_high[3] = result of A[3] == B[3])
    assign eq_high[0] = 1'b1;
    assign eq_high[1] = (A[2] == B[2]);
    assign eq_high[2] = (A[1] == B[1]);
    assign eq_high[3] = (A[3] == B[3]);

    // Compute A[i] > B[i] when higher bits are equal
    assign gt[0] = (A[0] > B[0]) & eq_high[0];
    assign gt[1] = (A[1] > B[1]) & eq_high[1];
    assign gt[2] = (A[2] > B[2]) & eq_high[2];
    assign gt[3] = (A[3] > B[3]) & eq_high[3];

    // Determine outputs
    assign A_greater = |gt;                // OR of all gt bits
    assign A_equal   = &eq_high;           // AND of all eq_high bits
    assign A_less    = ~A_greater & ~A_equal; // Not A_greater and not A_equal

endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    // Sign-extend inputs to 6 bits for accurate comparison
    wire [5:0] A_ext = { {2{A[3]}}, A };
    wire [5:0] B_ext = { {2{B[3]}}, B };

    // Perform comparisons using extended values
    assign A_greater = (A_ext > B_ext);
    assign A_equal   = (A_ext == B_ext);
    assign A_less    = (A_ext < B_ext);

endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    wire [3:0] diff;  // Unsigned difference (A > B)
    wire [4:0] diff_signed; // Signed difference (A - B, can be negative)
    wire A_greater_pre;  // Intermediate signal for A > B

    // Compute unsigned difference (A > B ? (A - B) : 4'b0)
    assign diff = (A > B) ? (A - B) : 4'b0;

    // Compute signed difference (A - B as 5-bit signed)
    assign diff_signed = { {1{A[3]}}, A } - { {1{B[3]}}, B };

    // Determine if A > B using signed comparison
    assign A_greater_pre = (diff_signed > 0);

    // Assign outputs based on intermediate signals
    assign A_greater = A_greater_pre;
    assign A_equal = (diff == 4'b0);
    assign A_less = ~A_greater & ~A_equal;

endmodule

