module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

reg prev_a;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		prev_a <= 1'b0;
		rise <= 1'b0;
		down <= 1'b0;
	} else begin
		// Compute next prev_a value
		reg next_prev_a;
		next_prev_a = a;

		// Compute next rise and down values
		reg next_rise, next_down;
		next_rise = next_prev_a & ~a;
		next_down = ~next_prev_a & a;

		// Update registers
		prev_a <= next_prev_a;
		rise <= next_rise;
		down <= next_down;
	}
end

endmodule

