module freq_divbyeven(
    input clk,
    input rst_n,
    output clk_div,
    reg clk_div;

    parameter NUM_DIV = 6;
    localparam COUNTER_WIDTH = (NUM_DIV == 1) ? 1 : $clog2(NUM_DIV);
    reg [COUNTER_WIDTH-1:0] counter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 0;
            clk_div <= 0;
        end else begin
            if (counter == NUM_DIV - 1) begin
                counter <= 0;
