module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// Signals in clk_a domain
	reg [3:0] data_reg;

	// Capture data_in on clk_a when data_en is asserted
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			data_reg <= 4'b0;
		end else begin
			if (data_en) begin
				data_reg <= data_in;
			end
		end
	 end

	// Synchronize data_reg to clk_b domain
	reg [3:0] sync_reg;

	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			sync_reg <= 4'b0;
		end else begin
			sync_reg <= data_reg;
		end
	 end

	// Update dataout with synchronized value
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			dataout <= 4'b0;
		end else begin
			dataout <= sync_reg;
		end
	 end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// Stage 1 registers for data_en and data_in
	reg data_en_stage1;
	reg [3:0] data_in_stage1;

	// Stage 2 registers to synchronize and hold data
	reg data_en_stage2;
	reg [3:0] data_in_stage2;

	// Stage 1: Capture data_en and data_in in clk_a domain
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			data_en_stage1 <= 1'b0;
			data_in_stage1 <= 4'b0;
		end else begin
			data_en_stage1 <= data_en;
			data_in_stage1 <= data_in;
		end
	end

	// Stage 2: Synchronize data_en and pass data_in to clk_b domain
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			data_en_stage2 <= 1'b0;
			data_in_stage2 <= 4'b0;
		end else begin
			data_en_stage2 <= data_en_stage1;
			if (data_en_stage1)
				data_in_stage2 <= data_in_stage1;
		end
	end

	// Output the synchronized data_in when data_en is high
	always @(*) begin
		if (data_en_stage2)
			dataout = data_in_stage2;
		else
			dataout = dataout; // Hold previous value (infer latch)
	end

endmodule

