	else begin
		if (data_en) begin
			data_a_reg <= data_in;
		end
	end
end

// Two-stage synchronizer in clk_b domain
always @(posedge clk_b or negedge brstn) begin
	if (!brstn) begin
		sync1 <= 1'b0;
		sync2 <= 1'b0;
	end
	else begin
		sync1 <= data_a_reg[0];
		sync2 <= sync1;
	end
end

// Update dataout with synchronized LSB
always @(posedge clk_b or negedge brstn) begin
	if (!brstn) begin
		dataout <= 4'b0;
	end
	else begin
		if (sync2) begin
			dataout <= data_a_reg;
		end
	end
end

endmodule

module synchronizer(
