module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// Signals in clk_a domain
	reg sync_a_0, sync_a_1;
	wire enable_a;

	// Synchronizer for enable_en in clk_a domain
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			sync_a_0 <= 1'b0;
			sync_a_1 <= 1'b0;
		end else begin
			sync_a_0 <= data_en;
			sync_a_1 <= sync_a_0;
		end
	end

	assign enable_a = sync_a_1;

	// Pipeline for data_in in clk_a domain
	reg [3:0] data_a;
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn)
			data_a <= 4'b0;
		else
			data_a <= data_in;
	end

	// Signals in clk_b domain
	reg sync_b_0, sync_b_1;
	reg [3:0] data_b;

	// Synchronizer for enable_a in clk_b domain
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			sync_b_0 <= 1'b0;
			sync_b_1 <= 1'b0;
		end else begin
			sync_b_0 <= enable_a;
			sync_b_1 <= sync_b_0;
		end
	end

	// Transfer data_a to clk_b domain when enable_a is high
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn)
			data_b <= 4'b0;
		else if (sync_b_1)
			data_b <= data_a;
	end

	// Assign the synchronized data to the output
	always @(*) begin
		dataout = data_b;
	end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

// State definitions
localparam S0 = 3'd0,
           S1 = 3'd1,
           S2 = 3'd2,
           S3 = 3'd3,
           S4 = 3'd4;

reg [2:0] current_state, next_state;

// Sequential state transition and reset handling
always @(posedge CLK or posedge RST) begin
    if (RST)
        current_state <= S0;
    else
        current_state <= next_state;
end

// Combinational next state logic
always @(*) begin
    case (current_state)
        S0: next_state = IN ? S1 : S0;
        S1: next_state = IN ? S1 : S2;
        S2: next_state = IN ? S1 : S3;
        S3: next_state = IN ? S4 : S0;
        S4: next_state = IN ? S1 : S0;
        default: next_state = S0;
    endcase
end

// Output logic based on current state
always @(posedge CLK or posedge RST) begin
    if (RST)
        MATCH <= 1'b0;
    else
        MATCH <= (current_state == S4);
end

endmodule

