module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

reg [1:0] counter;
reg temp1, temp2;
reg dout_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 2'b00;
        temp1 <= 1'b0;
        temp2 <= 1'b0;
        dout_reg <= 1'b0;
    end else begin
        counter <= (counter == 2'b10) ? 2'b00 : counter + 1'b1;
        case (counter)
            2'b00: begin
                temp1 <= d[0];
                dout_reg <= d[0];
            end
            2'b01: begin
                temp1 <= d[1];
                dout_reg <= d[1];
            end
            2'b10: begin
                temp1 <= d[2];
                dout_reg <= d[2];
            end
            default: begin
                temp1 <= d[3];
                dout_reg <= d[3];
            end
        endcase
    end
end

assign valid_out = (counter == 2'b10);
assign dout = dout_reg;

endmodule

